package com.aicharacter.v3;import java.util.*;
public final class MemoryConsolidationEngine {private MemoryConsolidationEngine(){}public static void consolidate(WorldState s,long now){if(s.memories.size()<120)return;Set<String>referenced=referencedIds(s);List<MemoryEntry>keep=new ArrayList<>(),minor=new ArrayList<>();for(MemoryEntry m:s.memories){double age=(now-m.time)/86400000.0;if(referenced.contains(m.memoryId)||m.importance>=.72||Math.abs(m.valence)>=.65||m.hasTag("identity")||m.hasTag("birthday"))keep.add(m);else if(age>30&&m.retrievalWeight(now)<.12)minor.add(m);else keep.add(m);}if(minor.size()>8){double v=0;for(MemoryEntry m:minor)v+=m.valence;keep.add(new MemoryEntry(now,"consolidated_reflection","Many smaller days have blended into a quieter long-term impression.",.48,v/minor.size(),.7,"",null,Arrays.asList("consolidated")));}s.memories.clear();s.memories.addAll(keep);while(s.memories.size()>220){int idx=-1;double weak=Double.MAX_VALUE;for(int i=0;i<s.memories.size();i++){MemoryEntry m=s.memories.get(i);if(referenced.contains(m.memoryId)||m.importance>=.8)continue;double w=m.retrievalWeight(now);if(w<weak){weak=w;idx=i;}}if(idx<0)break;s.memories.remove(idx);}}
 private static Set<String>referencedIds(WorldState s){Set<String>x=new HashSet<>();for(BeliefState b:s.beliefStates.values())for(BeliefEvidence e:b.evidence)if(!e.sourceMemoryId.isEmpty())x.add(e.sourceMemoryId);for(DiaryEntry d:s.diary)x.addAll(d.sourceMemoryIds);for(ThoughtState t:s.thoughts)x.addAll(t.relatedMemories);return x;}}
